class Solution {
public:
    int longestBalanced(string s) {
        int best=0,n=s.size();
        for(int i=0;i<n;++i) {
            int cnt[26]={0};
            for(int j=i;j<n;++j) {
                ++cnt[s[j]-'a'];
                int f=0;bool good=true;
                for(int c=0;c<26;++c) if(cnt[c]) {
                    if(!f) f=cnt[c];
                    else if(cnt[c]!=f) {good=false;break;}
                }
                if(good) best=max(best,j-i+1);
            }
        }
        return best;
    }
};
